'use strict';

/**
* Fill an input ndarray view according to a callback function.
*
* @module @stdlib/ndarray/fill-slice-by
*
* @example
* var zeros = require( '@stdlib/ndarray/zeros' );
* var MultiSlice = require( '@stdlib/slice/multi' );
* var Slice = require( '@stdlib/slice/ctor' );
* var fillSliceBy = require( '@stdlib/ndarray/fill-slice-by' );
*
* function clbk() {
*     return 5.0;
* }
*
* var x = zeros( [ 3, 4 ], {
*     'dtype': 'float64'
* });
*
* // Define the fill region:
* var s0 = new Slice( 1, 3 );
* var s1 = new Slice( 2, 4 );
* var s = new MultiSlice( s0, s1 );
*
* var y = fillSliceBy( x, s, clbk );
* // returns <ndarray>[ [ 0, 0, 0, 0 ], [ 0, 0, 5, 5 ], [ 0, 0, 5, 5 ] ]
*
* var bool = ( y === x );
* // returns true
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
